207	fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
208	    match Regex::new(&rule.pattern) {
209	        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
210	        Err(_) => text.to_string(),
211	    }
212	}
