214	fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
215	    let re = match Regex::new(&rule.pattern) {
216	        Ok(r) => r,
217	        Err(_) => return text.to_string(),
218	    };
219	    let lines: Vec<&str> = text.lines().collect();
220	    let filtered: Vec<&str> = lines
221	        .into_iter()
222	        .filter(|line| {
223	            let matches = re.is_match(line);
224	            if rule.invert { !matches } else { matches }
225	        })
226	        .collect();
227	    filtered.join("\n")
228	}
