230	fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
231	    let re = match Regex::new(&rule.pattern) {
232	        Ok(r) => r,
233	        Err(_) => return text.to_string(),
234	    };
235	    text.lines()
236	        .filter(|line| !re.is_match(line))
237	        .collect::<Vec<_>>()
238	        .join("\n")
239	}
