268	fn stage_max_lines(text: &str, max: usize) -> String {
269	    let lines: Vec<&str> = text.lines().collect();
270	    if lines.len() <= max {
271	        return text.to_string();
272	    }
273	    lines[..max].join("\n")
274	}
