1	use std::path::Path;
2	
3	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
4	pub enum ModelTier {
5	    Haiku,
6	    Sonnet,
7	    Opus,
8	}
9	
10	impl ModelTier {
11	    pub fn name(&self) -> &'static str {
12	        match self {
13	            ModelTier::Haiku => "haiku",
14	            ModelTier::Sonnet => "sonnet",
15	            ModelTier::Opus => "opus",
16	        }
17	    }
18	
19	    pub fn cost_per_million_tokens(&self) -> f64 {
20	        match self {
21	            ModelTier::Haiku => 0.25,
22	            ModelTier::Sonnet => 3.0,
23	            ModelTier::Opus => 15.0,
24	        }
25	    }
26	}
27	
28	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
29	pub enum Complexity {
30	    Low,
31	    Medium,
32	    High,
33	}
34	
35	pub struct RoutingInput {
36	    pub command: String,
37	    pub context_tokens: u64,
38	    pub file_extensions: Vec<String>,
39	    pub session_event_count: u64,
40	}
41	
42	pub struct RoutingDecision {
43	    pub tier: ModelTier,
44	    pub complexity: Complexity,
45	    pub score: f64,
46	    pub reason: String,
47	    pub estimated_savings_pct: f64,
48	}
49	
50	pub fn classify(input: &RoutingInput) -> RoutingDecision {
51	    let mut score: f64 = 0.5;
52	    let mut reasons = Vec::new();
53	
54	    // Command complexity
55	    let cmd_score = command_complexity(&input.command);
56	    score += cmd_score;
57	    if cmd_score.abs() > 0.05 {
58	        reasons.push(format!(
59	            "command '{}' complexity {:.2}",
60	            first_word(&input.command),
61	            cmd_score
62	        ));
63	    }
64	
65	    // Context size
66	    let ctx_score = context_complexity(input.context_tokens);
67	    score += ctx_score;
68	    if ctx_score.abs() > 0.05 {
69	        reasons.push(format!("context {}K tokens {:.2}", input.context_tokens / 1000, ctx_score));
70	    }
71	
72	    // File type complexity
73	    let ext_score = file_extension_complexity(&input.file_extensions);
74	    score += ext_score;
75	    if ext_score.abs() > 0.05 {
76	        reasons.push(format!("file types {:.2}", ext_score));
77	    }
78	
79	    // Session stage
80	    let stage_score = session_stage_complexity(input.session_event_count);
81	    score += stage_score;
82	    if stage_score.abs() > 0.05 {
83	        reasons.push(format!("session stage {:.2}", stage_score));
84	    }
85	
86	    score = score.clamp(0.0, 1.0);
87	
88	    let (complexity, tier) = if score < 0.3 {
89	        (Complexity::Low, ModelTier::Haiku)
90	    } else if score < 0.7 {
91	        (Complexity::Medium, ModelTier::Sonnet)
92	    } else {
93	        (Complexity::High, ModelTier::Opus)
94	    };
95	
96	    let default_cost = ModelTier::Opus.cost_per_million_tokens();
97	    let routed_cost = tier.cost_per_million_tokens();
98	    let savings_pct = if default_cost > 0.0 {
99	        (1.0 - routed_cost / default_cost) * 100.0
100	    } else {
101	        0.0
102	    };
103	
104	    RoutingDecision {
105	        tier,
106	        complexity,
107	        score,
108	        reason: reasons.join(", "),
109	        estimated_savings_pct: savings_pct,
110	    }
111	}
112	
113	fn first_word(cmd: &str) -> &str {
114	    cmd.split_whitespace().next().unwrap_or(cmd)
115	}
116	
117	fn command_complexity(command: &str) -> f64 {
118	    let cmd = command.to_lowercase();
119	    let first = first_word(&cmd);
120	
121	    let low_commands = [
122	        "git status", "git log", "git branch", "git diff --stat",
123	        "ls", "pwd", "cat", "head", "tail", "wc", "echo", "which", "whoami",
124	        "npm --version", "node --version", "cargo --version",
125	    ];
126	
127	    let high_commands = [
128	        "refactor", "architect", "design", "implement", "migrate",
129	        "review", "analyze", "debug", "optimize", "rewrite",
130	    ];
131	
132	    for lc in &low_commands {
133	        if cmd.starts_with(lc) {
134	            return -0.3;
135	        }
136	    }
137	
138	    for hc in &high_commands {
139	        if cmd.contains(hc) {
140	            return 0.3;
141	        }
142	    }
143	
144	    match first {
145	        "git" => -0.15,
146	        "ls" | "find" | "grep" | "cat" | "head" | "tail" => -0.2,
147	        "npm" | "pnpm" | "yarn" | "pip" | "cargo" => -0.1,
148	        "docker" | "kubectl" => 0.05,
149	        "python" | "node" | "go" | "rustc" => 0.1,
150	        _ => 0.0,
151	    }
152	}
153	
154	fn context_complexity(tokens: u64) -> f64 {
155	    match tokens {
156	        0..=1000 => -0.15,
157	        1001..=5000 => -0.05,
158	        5001..=20000 => 0.05,
159	        20001..=50000 => 0.15,
160	        _ => 0.25,
161	    }
162	}
163	
164	fn file_extension_complexity(extensions: &[String]) -> f64 {
165	    if extensions.is_empty() {
166	        return 0.0;
167	    }
168	
169	    let mut total = 0.0;
170	    for ext in extensions {
171	        total += match ext.as_str() {
172	            "md" | "txt" | "json" | "yaml" | "yml" | "toml" => -0.1,
173	            "html" | "css" | "scss" => -0.05,
174	            "js" | "ts" | "jsx" | "tsx" => 0.05,
175	            "py" | "rb" | "go" | "java" | "kt" => 0.1,
176	            "rs" | "cpp" | "c" | "h" => 0.15,
177	            "sql" | "graphql" | "proto" => 0.1,
178	            _ => 0.0,
179	        };
180	    }
181	
182	    (total / extensions.len() as f64).clamp(-0.2, 0.2)
183	}
184	
185	fn session_stage_complexity(event_count: u64) -> f64 {
186	    match event_count {
187	        0..=5 => -0.1,
188	        6..=20 => 0.0,
189	        21..=50 => 0.05,
190	        _ => 0.1,
191	    }
192	}
193	
194	pub fn extensions_from_paths(paths: &[&str]) -> Vec<String> {
195	    let mut exts: Vec<String> = paths
196	        .iter()
197	        .filter_map(|p| Path::new(p).extension())
198	        .filter_map(|e| e.to_str())
199	        .map(|e| e.to_lowercase())
200	        .collect();
201	    exts.sort();
202	    exts.dedup();
203	    exts
204	}
205	
206	#[cfg(test)]
207	mod tests {
208	    use super::*;
209	
210	    fn input(cmd: &str, tokens: u64, exts: &[&str], events: u64) -> RoutingInput {
211	        RoutingInput {
212	            command: cmd.to_string(),
213	            context_tokens: tokens,
214	            file_extensions: exts.iter().map(|e| e.to_string()).collect(),
215	            session_event_count: events,
216	        }
217	    }
218	
219	    #[test]
220	    fn test_simple_command_routes_to_haiku() {
221	        let decision = classify(&input("git status", 500, &[], 2));
222	        assert_eq!(decision.tier, ModelTier::Haiku);
223	        assert_eq!(decision.complexity, Complexity::Low);
224	        assert!(decision.estimated_savings_pct > 95.0);
225	    }
226	
227	    #[test]
228	    fn test_complex_command_routes_to_opus() {
229	        let decision = classify(&input("implement auth middleware", 60000, &["rs", "toml"], 40));
230	        assert_eq!(decision.tier, ModelTier::Opus);
231	        assert_eq!(decision.complexity, Complexity::High);
232	    }
233	
234	    #[test]
235	    fn test_medium_command_routes_to_sonnet() {
236	        let decision = classify(&input("cargo test", 10000, &["rs"], 15));
237	        assert_eq!(decision.tier, ModelTier::Sonnet);
238	        assert_eq!(decision.complexity, Complexity::Medium);
239	    }
