244	        assert_eq!(decision.tier, ModelTier::Haiku);
245	    }
246	
247	    #[test]
248	    fn test_refactor_routes_high() {
249	        let decision = classify(&input("refactor the auth module", 30000, &["ts", "tsx"], 30));
250	        assert!(decision.score >= 0.7);
251	        assert_eq!(decision.tier, ModelTier::Opus);
252	    }
253	
254	    #[test]
255	    fn test_large_context_increases_complexity() {
256	        let small = classify(&input("npm test", 500, &["js"], 10));
257	        let large = classify(&input("npm test", 80000, &["js"], 10));
258	        assert!(large.score > small.score);
259	    }
260	
