12	}
13	
14	impl FindingType {
15	    pub fn name(&self) -> &'static str {
16	        match self {
17	            FindingType::AwsKey => "aws_key",
18	            FindingType::GithubToken => "github_token",
19	            FindingType::PrivateKey => "private_key",
20	            FindingType::GenericSecret => "generic_secret",
21	            FindingType::Email => "email",
22	            FindingType::HighEntropy => "high_entropy",
23	        }
24	    }
25	
26	    pub fn severity(&self) -> &'static str {
27	        match self {
28	            FindingType::AwsKey | FindingType::PrivateKey => "critical",
29	            FindingType::GithubToken | FindingType::GenericSecret => "high",
30	            FindingType::HighEntropy => "medium",
31	            FindingType::Email => "low",
32	        }
33	    }
34	}
