    let json: serde_json::Value = serde_json::from_str(&settings).unwrap();

    let pre_hooks = json["hooks"]["PreToolUse"].as_array().unwrap();
    let matchers: Vec<&str> = pre_hooks
        .iter()
        .filter_map(|h| h["matcher"].as_str())
