const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080";
const TENANT_ID = process.env.NEXT_PUBLIC_TENANT_ID || "";

export interface OverviewStats {
  total_input_tokens: number;
  total_output_tokens: number;
  total_saved: number;
  savings_pct: number;
  event_count: number;
  top_commands: CommandStat[];
}

export interface CommandStat {
  command: string;
  saved: number;
  count: number;
}

export interface ProjectSummary {
  project_dir: string;
  total_saved: number;
  total_input: number;
  event_count: number;
  savings_pct: number;
  last_event_at: string;
}

export interface ProjectDailyStat {
  day: string;
  total_saved: number;
  total_input: number;
  event_count: number;
}

export interface ProjectStats {
  project_dir: string;
  summary: ProjectSummary;
  daily: ProjectDailyStat[];
  top_filters: CommandStat[];
}

export interface DailySavings {
  day: string;
  total_saved: number;
  total_input: number;
  event_count: number;
  compression_saved: number;
  dedup_saved: number;
}

async function apiFetch<T>(path: string): Promise<T> {
  if (!TENANT_ID) {
    console.error("NEXT_PUBLIC_TENANT_ID not set — API calls will fail");
  }
  const res = await fetch(`${API_URL}${path}`, {
    cache: "no-store",
    headers: {
      "X-Tenant-ID": TENANT_ID,
    },
  });
  if (!res.ok) {
    throw new Error(`API error: ${res.status}`);
  }
  return res.json();
}

export function fetchOverview(): Promise<OverviewStats> {
  return apiFetch("/v1/overview");
}

export function fetchProjects(): Promise<ProjectSummary[]> {
  return apiFetch("/v1/projects");
}

export function fetchProjectStats(projectDir: string): Promise<ProjectStats> {
  const normalized = projectDir.replaceAll("\\", "/");
  const encoded = normalized.replaceAll("/", "|");
  return apiFetch(`/v1/projects/${encodeURIComponent(encoded)}/stats`);
}

export function fetchSavingsTrend(days: number = 30): Promise<DailySavings[]> {
  return apiFetch(`/v1/savings/trend?days=${days}`);
}

export function formatTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
  return n.toString();
}

export function estimateCost(tokens: number): string {
  // Canonical pricing: cli/crates/core/src/router.rs — Sonnet $3/1M tokens
  const costPer1k = 0.003;
  const cost = (tokens / 1000) * costPer1k;
  if (cost < 0.01) return "<$0.01";
  return `$${cost.toFixed(2)}`;
}

export interface WasteReport {
  pattern_type: string;
  command: string;
  total_wasted: number;
  occurrences: number;
  session_count: number;
  suggestion: string;
}

export interface ProjectWasteScore {
  project_dir: string;
  total_wasted: number;
  total_input: number;
  waste_pct: number;
  pattern_count: number;
}

export function fetchWasteReport(days: number = 30): Promise<WasteReport[]> {
  return apiFetch(`/v1/waste?days=${days}`);
}

export function fetchProjectWasteScores(
  days: number = 30
): Promise<ProjectWasteScore[]> {
  return apiFetch(`/v1/waste/projects?days=${days}`);
}

export interface SecurityAlert {
  finding_type: string;
  severity: string;
  action: string;
  command: string;
  redacted_preview: string;
  detected_at: string;
  count: number;
}

export function fetchSecurityAlerts(
  days: number = 30
): Promise<SecurityAlert[]> {
  return apiFetch(`/v1/security/alerts?days=${days}`);
}

export interface ROISummary {
  total_input_tokens: number;
  total_saved: number;
  estimated_cost_saved: number;
  event_count: number;
  project_count: number;
  days_tracked: number;
  savings_pct: number;
  monthly: { month: string; input_tokens: number; tokens_saved: number; event_count: number }[];
}

export function fetchROISummary(days: number = 90): Promise<ROISummary> {
  return apiFetch(`/v1/roi?days=${days}`);
}

export async function exportCSV(days: number = 30): Promise<void> {
  const res = await fetch(`${API_URL}/v1/export/csv?days=${days}`, {
    headers: { "X-Tenant-ID": TENANT_ID },
  });
  if (!res.ok) throw new Error(`Export failed: ${res.status}`);
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `codeflow-export-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export interface BillingInfo {
  tenant_id: string;
  plan: string;
  status: string;
}

export function fetchBillingStatus(): Promise<BillingInfo> {
  return apiFetch("/v1/billing/status");
}

export async function createCheckout(): Promise<string> {
  const res = await fetch(`${API_URL}/v1/billing/checkout`, {
    method: "POST",
    headers: { "X-Tenant-ID": TENANT_ID },
  });
  if (!res.ok) throw new Error(`Checkout failed: ${res.status}`);
  const data = await res.json();
  return data.checkout_url;
}

export function shortProjectName(projectDir: string): string {
  const parts = projectDir.split(/[/\\]/).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : projectDir;
}

"use client";

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import {
  fetchOverview,
  fetchSavingsTrend,
  formatTokens,
  estimateCost,
  type OverviewStats,
  type DailySavings,
} from "@/lib/api";
import { useLiveMetrics } from "@/hooks/use-live-metrics";
import { DateRangeSelector } from "@/components/date-range-selector";

export default function OverviewPage() {
  const [stats, setStats] = useState<OverviewStats | null>(null);
  const [trend, setTrend] = useState<DailySavings[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [days, setDays] = useState(30);
  const { metrics: live, connected } = useLiveMetrics();

  useEffect(() => {
    setLoading(true);
    Promise.all([fetchOverview(), fetchSavingsTrend(days)])
      .then(([s, t]) => {
        setStats(s);
        setTrend(t || []);
      })
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, [days]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Overview</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              Could not connect to CODEFLOW API. Make sure the ingest server is
              running.
            </p>
            <p className="text-sm text-muted-foreground mt-2">
              Run:{" "}
              <code className="bg-muted px-1 rounded">
                cd cloud && go run ./cmd/ingest
              </code>
            </p>
          </CardContent>
        </Card>
        <DemoStats />
      </div>
    );
  }

  if (!stats || stats.event_count === 0) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Overview</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              No events yet. Install CODEFLOW hooks and start coding.
            </p>
            <p className="text-sm text-muted-foreground mt-2">
              Run:{" "}
              <code className="bg-muted px-1 rounded">
                codeflow init && codeflow sync --once
              </code>
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return <StatsView stats={stats} trend={trend} live={live} connected={connected} days={days} onDaysChange={setDays} />;
}

function StatsView({
  stats,
  trend,
  live,
  connected,
  days,
  onDaysChange,
}: {
  stats: OverviewStats;
  trend: DailySavings[];
  live: { tokens_saved_today: number; events_today: number } | null;
  connected: boolean;
  days: number;
  onDaysChange: (d: number) => void;
}) {
  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <h1 className="text-2xl font-bold">Overview</h1>
          {connected && (
            <span className="flex items-center gap-1.5 text-xs text-green-600">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse" />
              Live
            </span>
          )}
        </div>
        <DateRangeSelector value={days} onChange={onDaysChange} />
      </div>

      {live && (live.tokens_saved_today > 0 || live.events_today > 0) && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <MetricCard
            title="Saved This Session"
            value={formatTokens(live.tokens_saved_today)}
            description="tokens saved since page load"
          />
          <MetricCard
            title="Events This Session"
            value={live.events_today.toString()}
            description="new events since page load"
          />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          title="Tokens Saved"
          value={formatTokens(stats.total_saved)}
          description={`${estimateCost(stats.total_saved)} estimated savings`}
        />
        <MetricCard
          title="Savings Rate"
          value={`${stats.savings_pct.toFixed(1)}%`}
          description="of input tokens saved"
        />
        <MetricCard
          title="Events Tracked"
          value={formatTokens(stats.event_count)}
          description="command executions"
        />
        <MetricCard
          title="Input Tokens"
          value={formatTokens(stats.total_input_tokens)}
          description={`${formatTokens(stats.total_output_tokens)} after compression`}
        />
      </div>

      {trend.length > 0 && <SavingsTrendChart data={trend} />}

      {stats.top_commands && stats.top_commands.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Top Commands by Savings</CardTitle>
            <CardDescription>
              Commands with the highest token savings
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Command</TableHead>
                  <TableHead className="text-right">Tokens Saved</TableHead>
                  <TableHead className="text-right">Executions</TableHead>
                  <TableHead className="text-right">Est. Cost Saved</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {stats.top_commands.map((cmd) => (
                  <TableRow key={cmd.command}>
                    <TableCell>
                      <code className="bg-muted px-1.5 py-0.5 rounded text-sm">
                        {cmd.command}
                      </code>
                    </TableCell>
                    <TableCell className="text-right">
                      <Badge variant="secondary">
                        {formatTokens(cmd.saved)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">{cmd.count}x</TableCell>
                    <TableCell className="text-right">
                      {estimateCost(cmd.saved)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function SavingsTrendChart({ data }: { data: DailySavings[] }) {
  const formatted = data.map((d) => ({
    ...d,
    day: d.day.slice(5),
  }));

  return (
    <Card>
      <CardHeader>
        <CardTitle>Daily Savings Trend</CardTitle>
        <CardDescription>Tokens saved per day (last 30 days)</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="h-64">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={formatted}>
              <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
              <XAxis dataKey="day" className="text-xs" />
              <YAxis tickFormatter={(v) => formatTokens(Number(v))} className="text-xs" />
              <Tooltip
                formatter={(value, name) => [
                  formatTokens(Number(value)),
                  String(name) === "compression_saved" ? "Compression" : "Dedup",
                ]}
              />
              <Area
                type="monotone"
                dataKey="compression_saved"
                stackId="1"
                stroke="hsl(221, 83%, 53%)"
                fill="hsl(221, 83%, 53%)"
                fillOpacity={0.3}
                name="compression_saved"
              />
              <Area
                type="monotone"
                dataKey="dedup_saved"
                stackId="1"
                stroke="hsl(142, 71%, 45%)"
                fill="hsl(142, 71%, 45%)"
                fillOpacity={0.3}
                name="dedup_saved"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
}

function DemoStats() {
  const demo: OverviewStats = {
    total_input_tokens: 125000,
    total_output_tokens: 62500,
    total_saved: 62500,
    savings_pct: 50.0,
    event_count: 847,
    top_commands: [
      { command: "git diff", saved: 28000, count: 156 },
      { command: "git status", saved: 12400, count: 312 },
      { command: "cargo test", saved: 9800, count: 89 },
      { command: "npm test", saved: 7200, count: 142 },
      { command: "tsc", saved: 5100, count: 148 },
