});

export const metadata: Metadata = {
  title: "CODEFLOW Dashboard",
  description: "AI coding cost intelligence — see your token savings",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex">
        <AuthKitProvider>
          <Sidebar />
          <main className="flex-1 p-6 bg-background">
            <ErrorBoundary>{children}</ErrorBoundary>
          </main>
        </AuthKitProvider>
      </body>
    </html>
  );
}

function Sidebar() {
  return (
    <aside className="w-56 border-r bg-muted/40 p-4 flex flex-col">
      <div className="font-bold text-lg mb-4 tracking-tight">CODEFLOW</div>
      <nav className="flex flex-col gap-1 flex-1">
        <NavLink href="/">Overview</NavLink>
        <NavLink href="/projects">Projects</NavLink>
        <NavLink href="/waste">Waste</NavLink>
        <NavLink href="/roi">ROI</NavLink>
        <NavLink href="/security">Security</NavLink>
        <NavLink href="/billing">Billing</NavLink>
        <NavLink href="/settings">Settings</NavLink>
      </nav>
      <UserNav />
    </aside>
  );
}

function NavLink({
  href,
  children,
}: {
  href: string;
  children: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className="block px-3 py-2 rounded-md text-sm hover:bg-accent hover:text-accent-foreground transition-colors"
    >
      {children}
    </Link>
  );
}

